public class InnerDestinationEndpointDestinationEndpointConfigurationFactory(Action<Humidifier.MediaConnect.DestinationEndpointTypes.DestinationEndpointConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.DestinationEndpointTypes.DestinationEndpointConfiguration>
{

    internal InnerDestinationEndpointStandardDestinationEndpointConfigurationFactory StandardFactory { get; set; }

    internal InnerDestinationEndpointRouterInputDestinationEndpointConfigurationFactory RouterInputFactory { get; set; }

    protected override Humidifier.MediaConnect.DestinationEndpointTypes.DestinationEndpointConfiguration Create()
    {
        var destinationEndpointConfigurationResult = CreateDestinationEndpointConfiguration();
        factoryAction?.Invoke(destinationEndpointConfigurationResult);

        return destinationEndpointConfigurationResult;
    }

    private Humidifier.MediaConnect.DestinationEndpointTypes.DestinationEndpointConfiguration CreateDestinationEndpointConfiguration()
    {
        var destinationEndpointConfigurationResult = new Humidifier.MediaConnect.DestinationEndpointTypes.DestinationEndpointConfiguration();

        return destinationEndpointConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.DestinationEndpointTypes.DestinationEndpointConfiguration result)
    {
        base.CreateChildren(result);

        result.Standard ??= StandardFactory?.Build();
        result.RouterInput ??= RouterInputFactory?.Build();
    }

} // End Of Class

